La detección de packageManager se hace verificando archivos de lock en el filesystem:
- package-lock.json → npm
- yarn.lock → yarn
- pnpm-lock.yaml → pnpm
- bun.lockb → bun

async collect(): Promise<ContextData> {
  const pkgPath = path.join(this.projectRoot, 'package.json');

  if (!fs.existsSync(pkgPath)) {
    return {
      type: 'package-json',
      source: this.getName(),
      timestamp: new Date().toISOString(),
      priority: ContextPriority.Medium,
      data: { error: 'no-package-json', projectRoot: this.projectRoot }
    };
  }

  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
  const allDeps = {
    ...pkg.dependencies,
    ...pkg.devDependencies,
  };

  const stack = detectStack(allDeps, this.projectRoot);

  return {
    type: 'package-json',
    source: this.getName(),
    timestamp: new Date().toISOString(),
    priority: ContextPriority.High,
    data: {
      name: pkg.name,
      version: pkg.version,
      description: pkg.description,
      scripts: pkg.scripts ?? {},
      workspaces: pkg.workspaces ?? null,
      stack,
      dependencyCount: {
        production: Object.keys(pkg.dependencies ?? {}).length,
        development: Object.keys(pkg.devDependencies ?? {}).length,
      }
    }
  };
}
